import{_ as a,o as r,c as e,ag as o}from"./chunks/framework.CvZZEx4j.js";const b=JSON.parse('{"title":"背景与场景","description":"","frontmatter":{},"headers":[],"relativePath":"basics/backgrounds.md","filePath":"basics/backgrounds.md","lastUpdated":null}'),d={name:"basics/backgrounds.md"};function l(n,t,s,i,c,h){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="背景与场景" tabindex="-1">背景与场景 <a class="header-anchor" href="#背景与场景" aria-label="Permalink to &quot;背景与场景&quot;">​</a></h1><h2 id="背景图来源" tabindex="-1">背景图来源 <a class="header-anchor" href="#背景图来源" aria-label="Permalink to &quot;背景图来源&quot;">​</a></h2><p>插件支持多种背景图来源，可在设置面板的「生图配置」中切换：</p><table tabindex="0"><thead><tr><th>来源</th><th>说明</th></tr></thead><tbody><tr><td><strong>本地图库</strong></td><td>使用手动上传到资源管理器中的背景图</td></tr><tr><td><strong>ComfyUI</strong></td><td>连接本地 ComfyUI，AI 根据剧情实时生成背景</td></tr><tr><td><strong>大香蕉 (Banana)</strong></td><td>使用大香蕉 AI 生图服务生成背景</td></tr><tr><td><strong>NovelAI</strong></td><td>使用 NovelAI 的图像生成 API</td></tr><tr><td><strong>Wallhaven</strong></td><td>从 Wallhaven 壁纸库搜索匹配背景</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">最简单的方式</p><p>如果你不想配置 AI 生图，只需在资源管理器中手动上传背景图，AI 会从已有图库中选择匹配的场景。</p></div><h2 id="背景切换" tabindex="-1">背景切换 <a class="header-anchor" href="#背景切换" aria-label="Permalink to &quot;背景切换&quot;">​</a></h2><p>当 AI 输出中包含场景变化时，背景会自动切换，并带有平滑的过渡动画。</p><h2 id="场景色调" tabindex="-1">场景色调 <a class="header-anchor" href="#场景色调" aria-label="Permalink to &quot;场景色调&quot;">​</a></h2><p>插件会根据剧情中的时间氛围自动调整画面色调：</p><ul><li>☀️ 白天 —— 明亮色调</li><li>🌅 黄昏 —— 暖橙色调</li><li>🌙 夜晚 —— 偏蓝暗色调</li></ul><h2 id="填充模式" tabindex="-1">填充模式 <a class="header-anchor" href="#填充模式" aria-label="Permalink to &quot;填充模式&quot;">​</a></h2><p>在设置面板中可以切换背景图的填充方式：</p><ul><li><strong>Cover</strong>：背景图铺满整个画面（可能裁切边缘）</li><li><strong>Contain</strong>：完整显示背景图（可能留有黑边）</li></ul>',13)])])}const p=a(d,[["render",l]]);export{b as __pageData,p as default};
